}
vec2 waveSlope (vec2 p, float t) {
  vec2 g = vec2(0.0);
  vec2 d;
  d = vec2(0.8, 0.6);     g += d * (1.1 * 0.5)  * cos(dot(d, p) * 1.1 - t * 1.3);
  d = vec2(-0.5, 0.866);  g += d * (1.7 * 0.35) * cos(dot(d, p) * 1.7 - t * 1.7);
  d = vec2(0.2, -0.98);   g += d * (2.9 * 0.2)  * cos(dot(d, p) * 2.9 - t * 2.3);
  d = vec2(-0.94, -0.34); g += d * (4.3 * 0.12) * cos(dot(d, p) * 4.3 - t * 2.9);
  return g;
}
vec2 seaWaveSlope (vec2 p, float t) {
  vec2 g = vec2(0.0);
  vec2 d;
  d = vec2(0.9563, 0.2924);  g += d * 0.5  * cos(dot(d, p) * 1.13 - t * 1.3);
  d = vec2(-0.225, 0.9744);  g += d * 0.46 * cos(dot(d, p) * 1.79 - t * 1.7);
  d = vec2(0.4848, 0.8746);  g += d * 0.42 * cos(dot(d, p) * 2.83 - t * 2.3);
  d = vec2(-0.8572, 0.515);  g += d * 0.38 * cos(dot(d, p) * 4.37 - t * 2.9);
  d = vec2(-0.9816, 0.1908); g += d * 0.3  * cos(dot(d, p) * 6.7 - t * 3.4);
  d = vec2(-0.6018, 0.7986); g += d * 0.24 * cos(dot(d, p) * 9.1 - t * 3.9);
