const vec4 HOLE_K5 = vec4(0.0609, 0.0412, 0.0178, 0.0139);
float holeShapeDelta (vec2 d) {
  vec2 e = d / max(length(d), 1e-4);
  vec2 c = e;
  float s = 0.0;
  s += dot(HOLE_K0.xy, c); c = vec2(c.x * e.x - c.y * e.y, c.x * e.y + c.y * e.x);
  s += dot(HOLE_K0.zw, c); c = vec2(c.x * e.x - c.y * e.y, c.x * e.y + c.y * e.x);
  s += dot(HOLE_K1.xy, c); c = vec2(c.x * e.x - c.y * e.y, c.x * e.y + c.y * e.x);
  s += dot(HOLE_K1.zw, c); c = vec2(c.x * e.x - c.y * e.y, c.x * e.y + c.y * e.x);
  s += dot(HOLE_K2.xy, c); c = vec2(c.x * e.x - c.y * e.y, c.x * e.y + c.y * e.x);
  s += dot(HOLE_K2.zw, c); c = vec2(c.x * e.x - c.y * e.y, c.x * e.y + c.y * e.x);
  s += dot(HOLE_K3.xy, c); c = vec2(c.x * e.x - c.y * e.y, c.x * e.y + c.y * e.x);
  s += dot(HOLE_K3.zw, c); c = vec2(c.x * e.x - c.y * e.y, c.x * e.y + c.y * e.x);
  s += dot(HOLE_K4.xy, c); c = vec2(c.x * e.x - c.y * e.y, c.x * e.y + c.y * e.x);
  s += dot(HOLE_K4.zw, c); c = vec2(c.x * e.x - c.y * e.y, c.x * e.y + c.y * e.x);
  s += dot(HOLE_K5.xy, c); c = vec2(c.x * e.x - c.y * e.y, c.x * e.y + c.y * e.x);
  s += dot(HOLE_K5.zw, c);
  return s;
}
vec2 waveSlope (vec2 p, float t) {
  vec2 g = vec2(0.0);
  vec2 d;
  d = vec2(0.8, 0.6);     g += d * (1.1 * 0.5)  * cos(dot(d, p) * 1.1 - t * 1.3);
  d = vec2(-0.5, 0.866);  g += d * (1.7 * 0.35) * cos(dot(d, p) * 1.7 - t * 1.7);
  d = vec2(0.2, -0.98);   g += d * (2.9 * 0.2)  * cos(dot(d, p) * 2.9 - t * 2.3);
  d = vec2(-0.94, -0.34); g += d * (4.3 * 0.12) * cos(dot(d, p) * 4.3 - t * 2.9);
  return g;
}
vec2 seaWaveSlope (vec2 p, float t) {
  vec2 g = vec2(0.0);
  vec2 d;
  d = vec2(0.9563, 0.2924);  g += d * 0.5  * cos(dot(d, p) * 1.13 - t * 1.3);
  d = vec2(-0.225, 0.9744);  g += d * 0.46 * cos(dot(d, p) * 1.79 - t * 1.7);
  d = vec2(0.4848, 0.8746);  g += d * 0.42 * cos(dot(d, p) * 2.83 - t * 2.3);
  d = vec2(-0.8572, 0.515);  g += d * 0.38 * cos(dot(d, p) * 4.37 - t * 2.9);
  d = vec2(-0.9816, 0.1908); g += d * 0.3  * cos(dot(d, p) * 6.7 - t * 3.4);
  d = vec2(-0.6018, 0.7986); g += d * 0.24 * cos(dot(d, p) * 9.1 - t * 3.9);
  return g;
}
vec4 frag () {
  float t = cc_time.x * waveParams.y;
  vec2 q = v_worldPos.xz;
  vec2 hd = q - holeParams.xy;
  float r = length(hd);
  if (r < holeParams.z + 10.0) r -= holeShapeDelta(hd);
  float deep = 1.0 - smoothstep(holeParams.z - holeParams.w, holeParams.z + holeParams.w, r);
  float zone = 1.0 - smoothstep(holeParams.z, holeParams.z + 3.0, r);
#if WATER_SHORE && WATER_LITE && !WATER_UNDERSIDE
  zone = 0.0;
#endif
  float openWater = 0.0;
#if !WATER_UNDERSIDE
  vec3 sm = texture2D(seaMask, clamp((q - seaMaskRect.xy) / seaMaskRect.zw, 0.0, 1.0)).rgb;
  vec2 sa = abs(q);
  float od = max(max(sa.x, sa.y), (sa.x + sa.y) * 0.70710678);
  float sea = max(smoothstep(seaParams.x, seaParams.y, od), sm.g);
  float seaOpaque = max(max(sea, sm.b), smoothstep(seaParams.z, seaParams.w, od));
  openWater = max(seaOpaque, sm.r);
#endif
  float vary = max(zone, openWater);
  vec2 warp = vec2(0.0);
  float glintPatch = 1.0;
  if (vary > 0.0) {
    warp = glintVary.z * vary * vec2(sin(q.y * 0.37 + t * 0.21) + 0.6 * sin(q.x * 0.23 - q.y * 0.31),
                                     sin(q.x * 0.41 - t * 0.17) + 0.6 * sin(q.y * 0.27 + q.x * 0.19));
    float pn = sin(q.x * 0.29 + sin(q.y * 0.21) * 1.7 + t * 0.05) * sin(q.y * 0.33 - sin(q.x * 0.17) * 1.5 - t * 0.04);
    glintPatch = mix(1.0, mix(glintVary.y, 1.0, smoothstep(-0.55, 0.55, pn)), vary);
  }
  vec2 qw = q + warp;
  vec2 p = qw * waveParams.x;
#if WATER_SHORE && !WATER_UNDERSIDE
  vec2 g = (openWater < 1.0 && vary > 0.0) ? waveSlope(p, t) * vary : vec2(0.0);
#else
  vec2 g = openWater < 1.0 ? waveSlope(p, t) : vec2(0.0);
#endif
  if (zone > 0.0) {
    float c = glintVary.w * zone;
    vec2 d;
    d = vec2(0.6, -0.8);    g += d * (7.1 * 0.05 * c)  * cos(dot(d, p) * 7.1 - t * 3.4);
    d = vec2(-0.97, 0.24);  g += d * (9.3 * 0.035 * c) * cos(dot(d, p) * 9.3 - t * 3.9);
  }
  if (openWater > 0.0) g = mix(g, seaWaveSlope(p, t), openWater);
  g *= waveParams.z;
  vec3 n = normalize(vec3(-g.x, 1.0, -g.y));
  vec3 toCam = cc_cameraPos.xyz - v_worldPos;
  vec3 V = normalize(toCam);
#if WATER_SHORE && !WATER_UNDERSIDE
  float ripple = 0.5;
  float sparkle = 0.0;
  if (vary > 0.0) {
    float f = waveParams.x * 0.6;
    float w1 = sin(qw.x * f * 2.1 + t * 1.1) * sin(qw.y * f * 2.7 - t * 0.9);
    float w2 = sin((qw.x + qw.y) * f * 1.6 - t * 1.4) * sin((qw.x - qw.y) * f * 1.9 + t * 0.7);
    ripple = 0.5 + 0.25 * (w1 + w2) * vary;
    sparkle = pow(max(0.0, ripple), 14.0) * waveParams.w * glintPatch * (1.0 - glintDeep.z * deep) * vary;
  }
#else
  float f = waveParams.x * 0.6;
  float w1 = sin(qw.x * f * 2.1 + t * 1.1) * sin(qw.y * f * 2.7 - t * 0.9);
  float w2 = sin((qw.x + qw.y) * f * 1.6 - t * 1.4) * sin((qw.x - qw.y) * f * 1.9 + t * 0.7);
  float ripple = 0.5 + 0.25 * (w1 + w2);
  float sparkle = pow(max(0.0, ripple), 14.0) * waveParams.w * glintPatch * (1.0 - glintDeep.z * deep);
#endif
  vec4 col;
#if WATER_UNDERSIDE
  vec3 I = -V;
  float c = dot(I, n);
  float win = smoothstep(glintParams.z - glintParams.w, glintParams.z + glintParams.w, c);
  col = mix(undersideColor, windowColor, win);
  col.rgb *= 0.85 + 0.3 * ripple;
  float k = (c - glintParams.z) / max(0.005, glintParams.w * 0.6);
  float rim = exp(-k * k);
  col.rgb += windowColor.rgb * (rim * 0.35 + sparkle * win);
#else
#if WATER_SHORE
  vec2 shoreDist = shoreDistance(q);
  float shoreD = shoreDist.x;
  float beachD = shoreDist.y;
  float tone = smoothstep(0.0, 7.0, beachD);
  vec4 lagoon = mix(shoreShallow, shoreMid, smoothstep(0.0, 0.5, tone));
  lagoon = mix(lagoon, shoreFar, smoothstep(0.45, 1.0, tone));
  col = mix(lagoon, deepColor, deep);
#else
  col = mix(shallowColor, deepColor, deep);
#endif
  float e = (r - holeParams.z - holeParams.w) / max(0.05, holeParams.w);
  float edge = exp(-e * e);
  col.rgb = mix(col.rgb, edgeColor.rgb, edge * edgeColor.a);
  col = mix(col, laneColor, sm.r);
  col.rgb *= 0.92 + 0.16 * ripple;
  float nv = clamp(dot(n, V), 0.0, 1.0);
  float fres = (0.02 + 0.98 * pow(1.0 - nv, 5.0)) * skyColor.a;
#if WATER_SHORE
  float shallowReflection = (1.0 - deep) * (1.0 - openWater);
  fres = mix(fres, min(fres, 0.12), shallowReflection);
#endif
  col.rgb = mix(col.rgb, skyColor.rgb, fres);
  col.a = mix(col.a, 1.0, fres);
  vec3 L = normalize(-cc_mainLitDir.xyz);
  vec3 H = normalize(L + V);
#if WATER_SHORE
  float spec = vary > 0.0 ? pow(max(dot(n, H), 0.0), glintParams.x * (1.0 + glintDeep.x * deep)) * glintParams.y * vary : 0.0;
#else
  float spec = pow(max(dot(n, H), 0.0), glintParams.x * (1.0 + glintDeep.x * deep)) * glintParams.y;
#endif
  spec *= glintPatch * (1.0 - glintVary.x * deep);
  spec /= 1.0 + glintDeep.y * deep * spec;
  vec3 glint = cc_mainLitColor.rgb * spec + vec3(sparkle);
  col.rgb += glint;
  col.a = clamp(col.a + dot(glint, vec3(0.33)), 0.0, 1.0);
#if WATER_SHORE
  float shorePx = shorePixel(v_worldPos);
  #if !WATER_LITE
    float sunFlat = dot(vec3(-V.x, V.y, -V.z), L);
    if (sunFlat > glintWindow.y && openWater < 1.0) {
      float g1 = texture2D(glintMap, q * glintShape.x + vec2(cc_time.x * 0.070, -cc_time.x * 0.041)).r;
      float g2 = texture2D(glintMap, vec2(-q.y, q.x) * glintShape.y + vec2(-cc_time.x * 0.052, cc_time.x * 0.085)).r;
      vec2 slope = vec2(g1 - 0.5, g2 - 0.5) * glintShape.z;
      vec3 glintN = normalize(vec3(-slope.x, 1.0, -slope.y));
      float sun = pow(max(dot(reflect(-V, glintN), L), 0.0), glintWindow.x);
      float highlight = smoothstep(glintWindow.z, 1.0, sun) * g1 * g2;
      highlight *= (1.0 - deep * 0.6) * (1.0 - openWater) * (1.0 - smoothstep(0.09, 0.32, shorePx));
      col.rgb += vec3(highlight * glintWindow.w);
      col.a = clamp(col.a + highlight * glintShape.w, 0.0, 1.0);
    }
  #endif
#endif
  if (seaOpaque > 0.0) {
    float dist = length(toCam);
    float camH = max(cc_cameraPos.y - v_worldPos.y, seaWaveFade.w);
    float detail = 1.0 - smoothstep(seaWaveFade.y, seaWaveFade.z, dist * dist * seaWaveFade.x / camH);
    vec2 gs = g * detail;
    vec3 ns = normalize(vec3(-gs.x, 1.0, -gs.y));
    vec4 sc = seaColor;
    sc.rgb *= 0.92 + 0.16 * mix(0.5, ripple, detail);
    float nvs = clamp(dot(ns, V), 0.0, 1.0);
    float frs = (0.02 + 0.98 * pow(1.0 - nvs, 5.0)) * seaSkyColor.a;
    sc.rgb = mix(sc.rgb, seaSkyColor.rgb, frs);
    sc.a = mix(sc.a, 1.0, frs);
    float specS = pow(max(dot(ns, H), 0.0), mix(seaGlint.x, glintParams.x, detail)) * mix(seaGlint.y, glintParams.y, detail) * mix(1.0, glintPatch, detail);
    vec3 glintS = cc_mainLitColor.rgb * specS + vec3(sparkle * detail);
    sc.rgb += glintS;
    sc.a = clamp(sc.a + dot(glintS, vec3(0.33)), 0.0, 1.0);
    col.rgb = mix(col.rgb, sc.rgb, sea);
    col.a = mix(col.a, sc.a, seaOpaque);
  }
#if WATER_SHORE
  vec2 surf = vec2(0.0);
  float shoreScaleHere = shoreScale(shoreD, beachD);
#if WATER_LITE
  if (shoreD < 2.6) surf = shoreFoam(shoreD, shoreScaleHere, shoreSeed(q), q, cc_time.x, shorePx);
#else
  if (shoreD < 4.6) surf = shoreFoam(shoreD, shoreScaleHere, shoreSeed(q), q, cc_time.x, shorePx);
